        cancelPlan(cancelledOld, key("REQ"));
        mvc.perform(post("/api/v1/plans/{key}/reschedule", cancelledOld)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(rescheduleBody(key("REQ"), draftNew, 1, 1)))
