        assertThat(outcomes.stream().filter(o -> o == Outcome.OK).count()).isEqualTo(1);
        String newStatus = service.getPlan(newKey).status();
        String thirdStatus = service.getPlan(thirdParty).status();
        if (outcomes.get(0) == Outcome.OK) {
