                                + connKey + "\",\"predecessorScheduleKey\":\"" + pred
                                + "\",\"successorScheduleKey\":\"" + succ
                                + "\",\"guaranteeMinutes\":" + guarantee
                                + ",\"crossMidnight\":false}"))
                .andExpect(status().isCreated());
    }

