    private static String batchBody(String requestKey, String scheduleKey, int shiftMinutes) {
        return "{\"requestKey\":\"" + requestKey + "\",\"items\":[{\"scheduleKey\":\""
                + scheduleKey + "\",\"shiftMinutes\":" + shiftMinutes + "}]}";
    }
}
