        for (Future<ConnectionView> f : futures) {
            views.add(f.get(30, TimeUnit.SECONDS));
        }
        pool.shutdown();

        // 全部返回首次结果，库里只有一条接续
        assertThat(views).allMatch(v -> v.equals(views.get(0)));
